def draw_visual(c, kind, x, y, w, h):
    if kind == "pyongyang":
        # Pale sky, green mountains, a white office block, red flag.
        c.fill_rect(x, y, w, h, (200, 220, 235))
        c.polygon([(x, y + h), (x + w // 3, y + h // 3),
                   (x + 2 * w // 3, y + h)], (140, 170, 130))
        c.polygon([(x + w // 3, y + h), (x + 2 * w // 3, y + h // 4),
                   (x + w, y + h)], (120, 155, 120))
        c.fill_rect(x + w // 2 - 34, y + h - 30, 68, 30, WHITE)
        c.rect(x + w // 2 - 34, y + h - 30, 68, 30, INK, 1)
        for i in range(3):
            c.fill_rect(x + w // 2 - 26 + i * 20, y + h - 24, 10, 8,
                        (90, 130, 170))
        c.fill_rect(x + w // 2 + 34, y + h - 44, 2, 44, INK)
