# ---------------------------------------------------------------------------
# Map: equirectangular projection, simplified continents, numbered pins.
# ---------------------------------------------------------------------------

def project(lon, lat, mx, my, mw, mh):
    px = mx + (lon + 170.0) / 360.0 * mw
    py = my + (85.0 - lat) / 145.0 * mh
    return px, py


def pin_positions(mx, my, mw, mh):
    """Pixel positions for all 40 pins, with clusters spread on arcs and a
    short repulsion pass so no two pins hide each other's numbers."""
    all_stories = [(n, lat, lon, region) for (n, _h, _p, region, lat, lon, _s, _b, _v)
                   in HIGHLIGHTS]
    all_stories += [(n, lat, lon, region) for (n, _h, _p, region, lat, lon, _s)
                    in ALSO_ON]
    clustered = {}
    for cl in CLUSTERS:
        cx, cy = project(cl["centre"][1], cl["centre"][0], mx, my, mw, mh)
        n = len(cl["members"])
        for i, num in enumerate(cl["members"]):
            ang = -1.5708 + 6.28318 * i / n
            clustered[num] = (cx + cl["radius"] * _cos(ang),
                              cy + cl["radius"] * _sin(ang),
                              cx, cy)
    pos = {}
    true_xy = {}
    for num, lat, lon, region in all_stories:
        tx, ty = project(lon, lat, mx, my, mw, mh)
        true_xy[num] = (tx, ty)
        if num in clustered:
            px, py, _cx, _cy = clustered[num]
            pos[num] = [px, py]
        else:
            pos[num] = [tx, ty]
    # Repulsion: keep pin centres at least 16 px apart.
    order = sorted(pos)
    for _ in range(14):
        for i in range(len(order)):
            for j in range(i + 1, len(order)):
                a = pos[order[i]]
                b = pos[order[j]]
                dx = b[0] - a[0]
                dy = b[1] - a[1]
                d2 = dx * dx + dy * dy
                if d2 < 16.0 * 16.0 and d2 > 0.01:
                    d = d2 ** 0.5
                    push = (16.0 - d) / 2.0
                    ux, uy = dx / d, dy / d
                    a[0] -= ux * push
                    a[1] -= uy * push
                    b[0] += ux * push
                    b[1] += uy * push
        for num in order:
            p = pos[num]
            p[0] = max(mx + 9, min(mx + mw - 9, p[0]))
            p[1] = max(my + 9, min(my + mh - 9, p[1]))
    regions = {num: region for num, _lat, _lon, region in all_stories}
    return pos, true_xy, regions


def draw_map(c, mx, my, mw, mh):
    c.fill_rect(mx, my, mw, mh, SEA)
    for poly in CONTINENTS:
        pts = [(int(round(mx + (lon + 170.0) / 360.0 * mw)),
                int(round(my + (85.0 - lat) / 145.0 * mh))) for lon, lat in poly]
        c.polygon(pts, LAND)
        for i in range(len(pts)):
            x0, y0 = pts[i]
            x1, y1 = pts[(i + 1) % len(pts)]
            c.line(x0, y0, x1, y1, LAND_EDGE, 1)
    pos, true_xy, regions = pin_positions(mx, my, mw, mh)
    # Leader lines from spread pins back to their true city dot.
    for num in sorted(pos):
        px, py = pos[num]
        tx, ty = true_xy[num]
        if abs(px - tx) > 3 or abs(py - ty) > 3:
            c.line(int(round(tx)), int(round(ty)), int(round(px)), int(round(py)),
                   (90, 90, 90), 1)
            c.circle(int(round(tx)), int(round(ty)), 2, INK)
    for num in sorted(pos):
        px, py = pos[num]
        cx, cy = int(round(px)), int(round(py))
        colour = REGION_COLOURS.get(regions[num], NAVY)
        c.circle(cx, cy, 7, colour)
        c.ring(cx, cy, 7, WHITE, 1)
        label = str(num)
        tw = text_width(SB9, label)
        c.text(cx - tw // 2, cy + 3, SB9, label, WHITE)
        note("pin %d" % num, cx - 7, cy - 7, cx + 7, cy + 7)
    c.rect(mx, my, mw, mh, INK, 1)
    note("map", mx, my, mx + mw, my + mh)
    return pos


# Shorter bodies for the ten small highlight cards, condensed faithfully
# from the full bodies above so each fits its card: two lines where the
# headline takes three lines, three lines where it takes two.
SMALL_BODY = {
    4: "Oxfam: Gaza's air, soil and water stay dangerous for decades.",
    5: "Women's names erased from Balkh papers, replaced by 'Bibi'.",
    6: "FBI raids child centres in a $41 million fraud probe.",
    7: "Trump vows penalties for firms building data centres abroad.",
    8: "SK hynix rallies as Nvidia brings back Jensen Huang as CEO.",
    9: "Lahore's AQI tops 500, worst on Earth; eight Pakistan cities worst.",
    10: "O'Hare held departures briefly over a staffing shortage.",
    11: "Mossad foiled an ISIS-inspired plot against Swift's Vienna shows.",
    12: "Beijing says it wants no 'sphere of influence' after the summit.",
    13: "Charles reached out to Meghan after her father's arrest, expert says.",
}


def draw_lead_card(c, x, y, w, h, story):
    num, headline, place, region, _lat, _lon, source, body, kind = story
    colour = REGION_COLOURS.get(region, NAVY)
    c.rect(x, y, w, h, INK, 1)
    c.fill_rect(x + 1, y + 1, w - 2, 19, colour)
    label, src = fit_label(num, place, source, SB9, SB8, w - 6)
    c.text(x + 8, y + 15, SB9, label, WHITE)
    sw = text_width(SB8, src)
    c.text(x + w - 8 - sw, y + 14, SB8, src, WHITE)
    draw_visual(c, kind, x + 1, y + 20, w - 2, 44)
    lines = wrap_text(PF24, headline, w - 12)
    yy = y + 88
    for ln in lines[:2]:
        c.text(x + 6, yy, PF24, ln, INK)
        yy += 25
    note("lead %d headline" % num, x + 6, y + 88 - 24,
         x + 6 + max(text_width(PF24, ln) for ln in lines[:2]), yy - 25 + 6)
    body_lines = wrap_text(SR11, body, w - 12)
    yy = y + 138
    for ln in body_lines[:5]:
        c.text(x + 6, yy, SR11, ln, INK)
        yy += 13
    note("lead %d body" % num, x + 6, y + 138 - 11,
         x + 6 + max(text_width(SR11, ln) for ln in body_lines[:5]), yy - 13 + 4)
    note("lead %d card" % num, x, y, x + w, y + h)


def draw_small_card(c, x, y, w, h, story):
    num, headline, place, region, _lat, _lon, source, body, kind = story
    colour = REGION_COLOURS.get(region, NAVY)
    c.rect(x, y, w, h, INK, 1)
    c.fill_rect(x + 1, y + 1, w - 2, 15, colour)
    label, src = fit_label(num, place, source, SB8, SB8, w - 6)
    c.text(x + 6, y + 12, SB8, label, WHITE)
    sw = text_width(SB8, src)
    c.text(x + w - 6 - sw, y + 12, SB8, src, WHITE)
    draw_visual(c, kind, x + 1, y + 16, w - 2, 32)
    lines = wrap_text(PF15, headline, w - 12)
    yy = y + 66
    for ln in lines[:3]:
        c.text(x + 6, yy, PF15, ln, INK)
        yy += 17
    n_head = min(len(lines), 3)
    note("small %d headline" % num, x + 6, y + 66 - 15,
         x + 6 + max(text_width(PF15, ln) for ln in lines[:3]), yy - 17 + 5)
    body_lines = wrap_text(SR11, SMALL_BODY[num], w - 12)
    yy = y + 66 + 17 * (n_head - 1) + 13
    n_body = 0
    for ln in body_lines:
        if yy > y + 129 or n_body >= 3:
            break
        c.text(x + 6, yy, SR11, ln, INK)
        yy += 12
        n_body += 1
    if n_body:
        note("small %d body" % num, x + 6, y + 66 + 17 * (n_head - 1) + 2,
             x + 6 + max(text_width(SR11, ln) for ln in body_lines[:n_body]),
             yy - 12 + 4)
    note("small %d card" % num, x, y, x + w, y + h)


def draw():
    c = Canvas(W, H, PAPER)
    x0, x1 = 10, 1014
    cw = x1 - x0

    # Top band.
    c.fill_rect(x0, 8, cw, 20, INK)
    c.text(x0 + 8, 22, SB10, "THE WORLD IN ONE DAY", WHITE, track=2)
    right = "40 STORIES FROM ONE DAY"
    c.text(x1 - 8 - text_width(SB10, right, 2), 22, SB10, right, WHITE, track=2)
    note("top band", x0, 8, x1, 28)

    # Masthead and kicker.
    mast = "TUESDAY 24 NOVEMBER 2026"
    c.text(W // 2, 94, PF62, mast, INK, align="center")
    note("masthead", W // 2 - text_width(PF62, mast) // 2, 94 - 62,
         W // 2 + text_width(PF62, mast) // 2, 94 + 6)
    kicker = ("Pyongyang threatens Swiss office \u00b7 Gaza toxic for decades "
              "\u00b7 Lahore chokes at AQI 500 \u00b7 O'Hare ground stop")
    c.text(W // 2, 114, SR12, kicker, INK, align="center")
    note("kicker", W // 2 - text_width(SR12, kicker) // 2, 114 - 12,
         W // 2 + text_width(SR12, kicker) // 2, 114 + 4)
    c.fill_rect(x0, 122, cw, 2, GOLD)
    c.fill_rect(x0, 125, cw, 1, INK)

    # The day in UTC.
    ty = 130
    c.fill_rect(x0, ty, 104, 48, INK)
    c.text(x0 + 52, ty + 20, SB10, "THE DAY", WHITE, align="center")
    c.text(x0 + 52, ty + 34, SB10, "IN UTC", WHITE, align="center")
    cell_w = (x1 - (x0 + 108)) / 6.0
    for i, (t, label) in enumerate(TIMELINE):
        cx = x0 + 108 + i * cell_w
        if i:
            c.vline(int(round(cx)), ty + 4, 40, LIGHTGREY, 1)
        c.text(int(round(cx)) + 6, ty + 12, SB10, t, RED)
        lines = label.split("\n")
        yy = ty + 24
        for ln in lines:
            c.text(int(round(cx)) + 6, yy, SR10, ln, INK)
            yy += 11
        note("timeline %d" % i, int(round(cx)) + 6, ty + 2,
             int(round(cx)) + 6 + max(text_width(SR10, ln) for ln in lines),
             yy - 11 + 4)
    note("timeline block", x0, ty, x1, ty + 48)

    # Stat boxes.
    sy = 184
    for i, (big, label) in enumerate(STATS):
        bx = x0 + i * 168
        c.rect(bx, sy, 164, 50, INK, 1)
        c.text(bx + 82, sy + 26, PF26, big, INK, align="center")
        lns = label.split("\n")
        yy = sy + 38
        for ln in lns:
            c.text(bx + 82, yy, SB8, ln, GREY, align="center")
            yy += 10
        note("stat %d" % i, bx, sy, bx + 164, sy + 50)

    # Region bar: counts, then a segmented colour bar.
    c.text(W // 2, 250, SB9, REGION_BAR, INK, align="center")
    note("region bar", W // 2 - text_width(SB9, REGION_BAR) // 2, 250 - 9,
         W // 2 + text_width(SB9, REGION_BAR) // 2, 250 + 3)
    counts = [("EUROPE", 11, RED), ("EAST ASIA", 8, GREEN),
              ("AMERICAS", 7, BLUE), ("MIDDLE EAST", 7, GOLD),
              ("SOUTH ASIA", 5, PURPLE), ("SE ASIA", 1, ORANGE),
              ("AFRICA", 1, TEAL)]
    bx = x0
    for _name, n, colour in counts:
        seg = int(round(cw * n / 40.0))
        c.fill_rect(bx, 256, seg, 5, colour)
        bx += seg

    # Highlights: 3 large, then 10 small in two rows of five.
    lead_y, lead_h = 266, 204
    for i, story in enumerate(HIGHLIGHTS[:3]):
        draw_lead_card(c, x0 + i * 337, lead_y, 330, lead_h, story)
    small_y1, small_h = 474, 136
    for i, story in enumerate(HIGHLIGHTS[3:8]):
        draw_small_card(c, x0 + i * 202, small_y1, 196, small_h, story)
    small_y2 = 614
    for i, story in enumerate(HIGHLIGHTS[8:13]):
        draw_small_card(c, x0 + i * 202, small_y2, 196, small_h, story)

    # Section headers for the map and the further stories.
    map_x, map_y, map_w, map_h = x0, 772, 372, 176
    c.text(x0, 768, SB13, "WHERE IT HAPPENED", INK, track=1)
    note("map header", x0, 768 - 13, x0 + text_width(SB13, "WHERE IT HAPPENED", 1), 768 + 4)
    legend = "PINS 1\u201340 \u00b7 COLOUR = REGION"
    c.text(map_x + map_w - text_width(SB8, legend), 768, SB8, legend, GREY)
    note("map legend", map_x + map_w - text_width(SB8, legend), 768 - 8,
         map_x + map_w, 768 + 3)
    c.text(394, 768, SB13, "ALSO ON TUESDAY 24 NOVEMBER 2026 \u2014 27 MORE",
           INK, track=1)
    note("also header", 394, 768 - 13,
         394 + text_width(SB13, "ALSO ON TUESDAY 24 NOVEMBER 2026 \u2014 27 MORE", 1),
         768 + 4)

    # Map (left) and the 27 further stories (right, two columns).
    draw_map(c, map_x, map_y, map_w, map_h)
    col1 = ALSO_ON[:14]
    col2 = ALSO_ON[14:]
    for col_x, items in ((394, col1), (700, col2)):
        yy = map_y + 11
        for num, headline, place, _region, _lat, _lon, _src in items:
            line = "%d %s \u2014 %s" % (num, headline, place)
            c.text(col_x, yy, SR10, line, INK)
            yy += 12
        note("also col %d" % col_x, col_x, map_y + 11 - 10,
             col_x + max(text_width(SR10, "%d %s \u2014 %s" % (n, h, p))
                         for n, h, p, _r, _la, _lo, _s in items),
             yy - 12 + 4)

    # Date check box: sized from the measured wrapped text.
    dy = 952
    c.rect(x0, dy, cw, 40, RED, 1)
    c.text(x0 + 8, dy + 15, SB9, "DATE CHECK", RED)
    dc_lines = wrap_text(SR10, DATE_CHECK, 886)
    yy = dy + 12
    for ln in dc_lines:
        c.text(x0 + 118, yy, SR10, ln, INK)
        yy += 12
    note("date check", x0, dy, x1, dy + 40)
    note("date check text", x0 + 118, dy + 2,
         x0 + 118 + max(text_width(SR10, ln) for ln in dc_lines), yy - 12 + 4)

    # How we checked footer.
    fy = 996
    c.text(x0, fy + 12, SB9, "HOW WE CHECKED", INK)
    hw_lines = wrap_text(SR10, HOW_WE_CHECKED, 854)
    yy = fy + 10
    for ln in hw_lines:
        c.text(x0 + 150, yy, SR10, ln, INK)
        yy += 12
    note("footer", x0, fy, x1,
         yy - 12 + 4 if hw_lines else fy + 12)
    note("footer text", x0 + 150, fy,
         x0 + 150 + max(text_width(SR10, ln) for ln in hw_lines), yy - 12 + 4)

    return c


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    path = os.path.join(out_dir, "entry.png")
    canvas = draw()
    size = write_png(canvas, path)
    sys.stdout.write("wrote %s (%d bytes)\n" % (path, size))


if __name__ == "__main__":
    main()
